/*
 * Rebuilds the established knowledge pages into the frozen final page format.
 * Existing canonical URLs are retained. The output is original educational
 * content and deliberately states that independent engineering sign-off is
 * still required for project decisions.
 */
const fs = require("fs");
const path = require("path");

const root = __dirname;
const reviewDate = "30 August 2026";
const reviewFile = path.join(root, "outputs", "FINAL-KNOWLEDGE-PAGE-FORMAT-REVIEW.md");
const searchFile = path.join(root, "assets", "js", "site-search.js");
const esc = (value) => String(value || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
const pagePath = (route) => path.join(root, ...route.split("/"));
const rootRelative = (fromRoute, target) => {
  const from = path.posix.dirname(fromRoute) === "." ? "" : path.posix.dirname(fromRoute);
  let href = path.posix.relative(from, target) || "index.html";
  if (target.endsWith("/") && !href.endsWith("/")) href += "/";
  return href;
};
const canonical = (route) => `https://industrialcalculation.com/${route.replace(/index\.html$/, "")}`;

